sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    try {
        gs.info("📢 [API] - Processing Incoming Request for procurement.form property...");



        // For PUT or POST requests - update/create property value
        if (method === 'PUT' || method === 'POST') {
            // Safely extract request body data
            var requestBody;
            if (request && request.body) {
                if (typeof request.body === 'string') {
                    try {
                        requestBody = JSON.parse(request.body);
                    } catch (e) {
                        requestBody = request.body;
                    }
                } else if (request.body.data) {
                    requestBody = request.body.data;
                } else {
                    requestBody = request.body;
                }
            }

            gs.info("🔵 Request Body: " + JSON.stringify(requestBody));

            // Check if data exists and has required properties
            if (!requestBody || requestBody.value === undefined) {
                gs.error("❌ Missing required data: value");
                response.setStatus(400);
                response.setBody({ error: "Missing required data: value" });
                return;
            }

            var propertyValue = requestBody.value;
            gs.info("📝 Setting property value: " + propertyValue);

            // Check if property exists for proper response messaging
            var propertyExists = gs.getProperty('procurement.form') !== null;

            // Set the system property
            var result = gs.setProperty('procurement.form', propertyValue);

            if (result !== null) {
                if (method === 'POST' && !propertyExists) {
                    gs.info("✅ System Property Successfully Created");
                    response.setStatus(201);
                    response.setBody({
                        message: "✅ System property 'procurement.form' created successfully!",
                        property_name: 'procurement.form'
                    });
                } else {
                    gs.info("✅ System Property Successfully Updated");
                    response.setStatus(200);
                    response.setBody({
                        message: "✅ System property 'procurement.form' updated successfully!",
                        property_name: 'procurement.form'
                    });
                }
            } else {
                gs.error("❌ System Property Operation Failed");
                response.setStatus(500);
                response.setBody({ 
                    error: method === 'POST' ? "Failed to create system property" : "Failed to update system property" 
                });
            }
            return;
        }

        // Handle unsupported methods
        gs.warn("⚠️ Unsupported Method: " + method);
        response.setStatus(405);
        response.setBody({ error: "Method not allowed" });

    } catch (e) {
        gs.error("❌ Exception: " + e.message);
        response.setStatus(500);
        response.setBody({ error: "Exception occurred: " + e.message });
    }
})(request, response);





